/// <summary>
/// MPJ_3338_AMEXCustomerPaymentProcessing - vpotula
/// Extension of <c>ledgerJournalCheckPost</c> class
/// </summary>
[ExtensionOf(classStr(ledgerJournalCheckPost))]
public final class METLedgerJournalCheckPost_Extension
{
}

Method.Source:
    /// <summary>
    /// Extended stand method to update AMEX journal number.
    /// </summary>
    /// <returns>LedgerJournalId</returns>
    public LedgerJournalId transferToNewLedgerTable()
    {
        JournalId    metNewJournal = next transferToNewLedgerTable();

        //MPJ_3338_AMEXCustomerPaymentProcessing - vpotula
        if(!CustParameters::find().METAMEXIsAdhocJournal)
        {
            LedgerJournalTable  metNewJournalTable = LedgerJournalTable::find(metNewJournal, false);
            if (metNewJournalTable
                && metNewJournalTable.JournalName == CustParameters::find().METAMEXJournalName)
            {
                CustParameters::METUpdateAMEXJournalNum(metNewJournal);
            }
        }
        return metNewJournal;
    }
